{
  "name": "opencode-capture",
  "version": "0.1.0",
  "description": "opencode plugin that captures session traces (reasoning, tool calls, text, files) as JSONL for the CMF recorder.",
  "type": "module",
  "main": "dist/plugin.js",
  "types": "dist/plugin.d.ts",
  "exports": {
    ".": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    }
  },
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "test": "tsx --test test/*.test.ts",
    "prepublishOnly": "npm run build"
  },
  "files": ["dist"],
  "license": "ISC",
  "author": "atripathy86 <atripathy86@gmail.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/atripathy86/opencode-capture.git"
  },
  "homepage": "https://github.com/atripathy86/opencode-capture#readme",
  "bugs": {
    "url": "https://github.com/atripathy86/opencode-capture/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cmf",
    "trace",
    "capture",
    "lineage",
    "coding-agent"
  ],
  "devDependencies": {
    "@opencode-ai/sdk": "^1.18.13",
    "@opencode-ai/plugin": "^1.18.13",
    "@types/node": "^22.0.0",
    "tsx": "^4.23.1",
    "typescript": "^5.6.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  }
}
